  const focusEditableNode = (node, atEnd = true) => {
    if (!node) return;
    node.focus();
    const selection = window.getSelection();
    if (selection) {
      const range = document.createRange();
      range.selectNodeContents(node);
      range.collapse(!atEnd);
      selection.removeAllRanges();
      selection.addRange(range);
    }
  };

  const focusEditableNodeAtOffset = (node, offset) => {
    if (!node) return;
    node.focus();
    const selection = window.getSelection();
    if (selection) {
      const range = document.createRange();
      let textNode = null;
      if (node.firstChild) {
        if (node.firstChild.nodeType === Node.TEXT_NODE) {
          textNode = node.firstChild;
        } else {
          let curr = node.firstChild;
          while (curr && curr.nodeType !== Node.TEXT_NODE) {
            curr = curr.firstChild;
          }
          textNode = curr;
        }
      }
      if (textNode) {
        const maxOffset = textNode.length;
        range.setStart(textNode, Math.min(offset, maxOffset));
        range.setEnd(textNode, Math.min(offset, maxOffset));
      } else {
        range.selectNodeContents(node);
        range.collapse(true);
      }
      selection.removeAllRanges();
      selection.addRange(range);
    }
  };

  const isSelectionAtStartOfNode = (node) => {
    if (!node) return false;
    const selection = window.getSelection();
    if (!selection || !selection.rangeCount) return false;
    const range = selection.getRangeAt(0);
    if (!node.contains(range.startContainer)) {
      return false;
    }
    
    if (range.startContainer === node && range.startOffset === 0) {
      return true;
    }
    
    let current = range.startContainer;
    let offset = range.startOffset;
    
    if (current.nodeType === Node.TEXT_NODE) {
      if (offset > 0) return false;
    } else {
      if (offset > 0) {
        for (let i = 0; i < offset; i++) {
          const child = current.childNodes[i];
          if (child && child.nodeType !== Node.COMMENT_NODE && (child.textContent?.length > 0 || child.nodeName === 'BR' || child.nodeType === Node.ELEMENT_NODE)) {
            return false;
          }
        }
      }
    }
    
    while (current && current !== node) {
      let sibling = current.previousSibling;
      while (sibling) {
        if (sibling.nodeType !== Node.COMMENT_NODE && (sibling.textContent?.length > 0 || sibling.nodeType === Node.ELEMENT_NODE)) {
          return false;
        }
        sibling = sibling.previousSibling;
      }
      current = current.parentNode;
    }
    return true;
  };



