            const text = node.textContent;
            let formatTag = null;
            if (text === '#') formatTag = 'H1';
            else if (text === '##') formatTag = 'H2';
            else if (text === '###') formatTag = 'H3';
            else if (text === '>') formatTag = 'BLOCKQUOTE';
            else if (text === '-') formatTag = 'UL';
            
