  const activeSheet = sheetsData.find((sheet) => sheet.id === activeSheetId) || sheetsData[0];
  const rawSheetGrid = sheetGrids[activeSheetId] || (activeSheet ? sheetGrids[activeSheet.id] : null);
  const activeSheetGridRaw = {
    rows: (rawSheetGrid?.rows && typeof rawSheetGrid.rows === 'number' && rawSheetGrid.rows > 0) ? rawSheetGrid.rows : 22,
    cols: (rawSheetGrid?.cols && typeof rawSheetGrid.cols === 'number' && rawSheetGrid.cols > 0) ? rawSheetGrid.cols : 26,
    cells: (rawSheetGrid?.cells && rawSheetGrid.cells.length > 0) ? rawSheetGrid.cells : Array.from({ length: 22 }, () => Array(26).fill('')),
    formats: rawSheetGrid?.formats || {},
    tables: rawSheetGrid?.tables || [],
    overlays: rawSheetGrid?.overlays || [],
    filters: rawSheetGrid?.filters || {}
  };
  
  const activeSheetGrid = useMemo(() => {
    if (!activeSheetGridRaw) return { rows: 22, cols: 26, cells: Array.from({ length: 22 }, () => Array(26).fill('')), formats: {}, tables: [], overlays: [], filters: {} };
    const rows = (activeSheetGridRaw.rows && typeof activeSheetGridRaw.rows === 'number' && activeSheetGridRaw.rows > 0) ? activeSheetGridRaw.rows : 22;
    const cols = (activeSheetGridRaw.cols && typeof activeSheetGridRaw.cols === 'number' && activeSheetGridRaw.cols > 0) ? activeSheetGridRaw.cols : 26;
    const parser = new Parser();
    
    parser.on('callCellValue', (cellCoord, done) => {
      const rowIndex = cellCoord.row.index;
      const colIndex = cellCoord.column.index;
      const val = activeSheetGridRaw.cells?.[rowIndex]?.[colIndex];
      done(val);
    });

    parser.on('callRangeValue', (startCellCoord, endCellCoord, done) => {
      const fragment = [];
      for (let row = startCellCoord.row.index; row <= endCellCoord.row.index; row++) {
        const rowData = activeSheetGridRaw.cells?.[row];
        const colFragment = [];
        for (let col = startCellCoord.column.index; col <= endCellCoord.column.index; col++) {
          colFragment.push(rowData ? rowData[col] : null);
        }
        fragment.push(colFragment);
      }
      done(fragment);
    });

    const evaluatedCells = (activeSheetGridRaw.cells || []).map((row, r) => 
      (row || []).map((cell, c) => {
        const cellFormat = activeSheetGridRaw.formats?.[r]?.[c] || {};
        const isLocked = Boolean(cellFormat.isLocked || cellFormat.locked);

        if (typeof cell === 'string') {
          let raw = cell.trim();
          if (!raw) return cell;

          // 1. Explicit formula starting with '=' or '+' (e.g. '=1+1', '= 1+1', '+1+1', '+ 1+1')
          if (raw.startsWith('=') || (raw.startsWith('+') && raw.length > 1 && !/^\+\d{1,4}[-\/]\d{1,2}/.test(raw))) {
            let expr = raw.substring(1).trim();
            if (expr.endsWith('=')) expr = expr.slice(0, -1).trim();
            const result = parser.parse(expr);
            return (!result.error && result.result !== null && typeof result.result !== 'undefined') ? result.result : (result.error || cell);
          }

          // 2. Trailing equal like '1+1='
          if (raw.endsWith('=') && raw.length > 1) {
            if (isLocked) return cell;
            const expr = raw.slice(0, -1).trim();
            const result = parser.parse(expr);
            if (!result.error && result.result !== null && typeof result.result !== 'undefined') {
              return result.result;
            }
          }

          // 3. Implicit formula calculation without leading '=' or '+' (when cell is unlocked)
          // Exclude dates (e.g. 2026-07-20) and phone numbers
          if (!isLocked && 
              !/^\d{1,4}[-\/]\d{1,2}[-\/]\d{1,4}$/.test(raw) && 
              !/^\d{3,4}-\d{3,4}-\d{4}$/.test(raw)) {
            
            const hasOperators = /[\+\-\*\/\^\%]/.test(raw);
            const isFn = /^[A-Z]{2,}\s*\(.*?\)$/i.test(raw);
            const isMathExpr = isNaN(raw) && (hasOperators || isFn);

            if (isMathExpr) {
              const result = parser.parse(raw);
              if (!result.error && result.result !== null && typeof result.result !== 'undefined') {
                return result.result;
              }
            }
          }
        }
        return cell;
      })
    );

    return {
      ...activeSheetGridRaw,
      rows,
      cols,
      cells: evaluatedCells
    };
  }, [activeSheetGridRaw]);
